  writes.write(handle(),f.source,RECEIPT,c,()->{journal.received(a,new com.disasterinfo.eodiisseo.collection.execution.CollectionProviderPort.Reply(200,bytes,Duration.ZERO),policy.inspect(bytes),policy);return null;});
